def train_with_error_handling(model, train_ds, val_ds, epochs=2):
    """Train model, skipping batches with data errors"""
    import math
    best_val_loss = float('inf')
    wait = 0

    for epoch in range(epochs):
        print(f'\nEpoch {epoch + 1}/{epochs}')
        batch_count = 0
        total_batches = math.ceil(735 / batch_size)  # approximate

        for step, (x_batch, y_batch) in enumerate(train_ds):
            try:
                # Train on this batch
                metrics = model.train_on_batch(x_batch, y_batch, return_dict=True)
                batch_count += 1
            except Exception as e:
                # Skip this batch if there's a data error
                print(f"Skipping batch {step} due to data error: {type(e).__name__}")
                continue

        # Validation
        val_metrics = {}
        for val_step, (x_val, y_val) in enumerate(val_ds):
            try:
                val_metrics = model.test_on_batch(x_val, y_val, return_dict=True)
            except Exception as e:
                # Skip bad validation batch
                continue

        # Print metrics
        if batch_count > 0 and 'loss' in metrics:
            print(f"{batch_count}/{total_batches} - loss: {metrics['loss']:.4f} - accuracy: {metrics['accuracy']:.4f}", end="")
            if 'loss' in val_metrics:
                print(f" - val_loss: {val_metrics['loss']:.4f} - val_accuracy: {val_metrics['accuracy']:.4f}")
            else:
                print()

        # Early stopping check
        if 'loss' in val_metrics and val_metrics['loss'] < best_val_loss:
            best_val_loss = val_metrics['loss']
            wait = 0
        else:
            wait += 1
            if wait >= 5:
                print("Early stopping triggered")
                break

    return model

